from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .fraud_check_result import FraudCheckResult, FraudCheckResultDict


class FraudResult(SdkBaseModel):
    account_score: int = Field(alias="accountScore")
    """The total fraud score generated by the risk checks."""

    results: Optional[list[FraudCheckResult]] = UNSET
    """The result of the individual risk checks."""


class FraudResultDict(TypedDict):
    account_score: int
    results: NotRequired[list[FraudCheckResultDict]]
